from datetime import datetime
import re

def parse_date(text: str) -> datetime.date:
    text = text.strip()

    # ISO format: YYYY-MM-DD
    iso_match = re.match(r'^(\d{4})-(\d{2})-(\d{2})$', text)
    if iso_match:
        try:
            return datetime.strptime(text, "%Y-%m-%d").date()
        except ValueError:
            raise ValueError(f"Invalid ISO date format or date value: {text}")

    # British numeric: DD/MM/YYYY
    british_match = re.match(r'^(\d{2})/(\d{2})/(\d{4})$', text)
    if british_match:
        try:
            return datetime.strptime(text, "%d/%m/%Y").date()
        except ValueError:
            raise ValueError(f"Invalid British date format or date value: {text}")

    # Short text: D Mon YYYY (e.g., "7 Mar 2025")
    short_match = re.match(r'^(\d{1,2})\s+(\w{3})\s+(\d{4})$', text)
    if short_match:
        day_str, month_str, year_str = short_match.groups()
        # Normalize day to zero-padded string for parsing
        day_padded = f"{int(day_str):02}"

        months = {
            'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
            'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
        }

        if month_str.lower() not in months:
            raise ValueError(f"Invalid month name: {month_str}")

        try:
            return datetime.strptime(f"{day_padded} {months[month_str.lower()]} {year_str}", "%d %m %Y").date()
        except ValueError:
            raise ValueError(f"Invalid short date format or date value: {text}")

    raise ValueError(f"Unsupported date format: {text}")
