function parseQuery(qs) {
  if (!qs || typeof qs !== 'string') return {};

  // Remove leading '?' if present
  let str = qs.replace(/^\?/, '');
  const result = {};
  const parts = str.split('&');

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i].trim();

    // Skip empty pairs
    if (!part) continue;

    const eqIndex = part.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      // Key without value
      key = decodeURIComponent(part.replace(/\+/g, ' '));
      value = '';
    } else {
      // Split on the FIRST '='
      key = decodeURIComponent(part.slice(0, eqIndex).replace(/\+/g, ' '));
      value = decodeURIComponent(part.slice(eqIndex + 1).replace(/\+/g, ' '));
    }

    if (key === '') continue; // Skip empty keys

    if (result[key]) {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value);
    } else {
      result[key] = value;
    }
  }

  return result;
}
