  if (override === null || typeof override !== 'object') {
    return override;
  }

  const target = Object.create(null); // Create new object without prototype

  for (const key in base) {
    if (Object.prototype.hasOwnProperty.call(base, key)) {
      target[key] = deepMerge(base[key], undefined); // Undefined in override keeps base value
    }
  }

  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const baseVal = base && base[key];
      const overrideVal = override[key];

      // If override is null, it replaces the value; otherwise check for deep merge
      if (overrideVal === null || (typeof overrideVal === 'object' && overrideVal !== null)) {
        target[key] = deepMerge(baseVal, overrideVal);
      } else {
        target[key] = overrideVal;
      }
    }
  }

  return target;
}
