class Page:
    number: int
    items: list
    has_next: bool


class Paginator:
    """Splits a list of search results into 1-based pages."""

    def __init__(self, items: list, page_size: int):
        if page_size < 1:
            raise ValueError("page_size must be >= 1")
        self.items = items
        self.page_size = page_size

    @property
    def page_count(self) -> int:
        return len(self.items) // self.page_size + (1 if len(self.items) % self.page_size else 0)

    def get_page(self, number: int) -> Page:
        if number < 1 or number > max(self.page_count, 1):
            raise ValueError(f"page {number} out of range")
        start = (number - 1) * self.page_size
        end = start + self.page_size
        return Page(
            number=number,
            items=self.items[start:end],
            has_next=number < self.page_count,
        )
